if (twentyFives == 0) {
    units -= units % 2;
    possible = smallerBoxesFit(weight - units * 25, ones, fives, tens);
} else {
    possible = smallerBoxesFit(weight - units * 25, ones, fives, tens);
    if (!possible && units > 0)
        possible = smallerBoxesFit(weight - (units - 1) * 25, ones, fives, tens);
}
